<?php

declare(strict_types=1);

namespace App\Application\Command\CreateUser;

use App\Application\Command\CommandInterface;
use App\Application\Validation\Field;
use App\Domain\ValueObject\User\UserEmail;
use App\Domain\ValueObject\User\UserId;
use App\Domain\ValueObject\User\UserName;

final readonly class CreateUserCommand implements CommandInterface
{
    private UserId $userId;
    private UserEmail $email;
    private UserName $name;

    /**
     * @param string $userId generated by the sender, so it can read the user back afterwards
     */
    public function __construct(string $userId, string $email, string $name)
    {
        $this->userId = Field::of('userId', static fn (): UserId => UserId::fromString($userId));
        $this->email  = Field::of('email', static fn (): UserEmail => UserEmail::fromString($email));
        $this->name   = Field::of('name', static fn (): UserName => UserName::fromString($name));
    }

    public function getUserId(): UserId
    {
        return $this->userId;
    }

    public function getEmail(): UserEmail
    {
        return $this->email;
    }

    public function getName(): UserName
    {
        return $this->name;
    }
}
